package com.hotel.booking.service;
import com.hotel.booking.dao.BookingDAO;import com.hotel.booking.dao.RoomDAO;import com.hotel.booking.model.Booking;import com.hotel.booking.model.Room;import java.sql.SQLException;import java.sql.Date;import java.time.LocalDate;import java.time.temporal.ChronoUnit;import java.math.BigDecimal;import java.util.List;
public class BookingService {private final BookingDAO dao=new BookingDAO();private final RoomDAO rooms=new RoomDAO();public Booking book(int customerId,int roomId,LocalDate in,LocalDate out)throws SQLException{if(customerId<=0||roomId<=0||in==null||out==null||!out.isAfter(in)||in.isBefore(LocalDate.now()))throw new IllegalArgumentException("Please enter valid customer, room and future booking dates.");Room room=rooms.byId(roomId);if(room==null||!"AVAILABLE".equals(room.getStatus()))throw new IllegalArgumentException("Room not found or not available for booking.");if(!dao.isRoomAvailable(roomId,Date.valueOf(in),Date.valueOf(out)))throw new IllegalArgumentException("Room already booked for those dates.");long nights=ChronoUnit.DAYS.between(in,out);BigDecimal total=room.getPricePerNight().multiply(BigDecimal.valueOf(nights));return dao.add(new Booking(customerId,roomId,in,out,total));}public List<Booking> all()throws SQLException{return dao.all();}public boolean cancel(int id)throws SQLException{return dao.cancel(id);}}
